import React, { useState, useEffect } from 'react';
import '../styles/Team.css';
import Button from '../components/Button';

const Team = () => {
  const [search, setSearch] = useState('');
  const [results, setResults] = useState([]);
  const [team, setTeam] = useState(Array(6).fill(null));

  useEffect(() => {
    if (search.length >= 2) {
      fetch(`https://pokeapi.co/api/v2/pokemon?limit=1000`)
        .then(res => res.json())
        .then(data => {
          const filtered = data.results.filter(p =>
            p.name.toLowerCase().includes(search.toLowerCase())
          );
          setResults(filtered.slice(0, 10));
        });
    } else {
      setResults([]);
    }
  }, [search]);

  const handleSearch = e => {
    setSearch(e.target.value);
  };

  const addToTeam = async (pokemonData) => {
    const index = team.findIndex(p => p === null);
    if (index !== -1) {
      const res = await fetch(pokemonData.url);
      const details = await res.json();
      const updatedTeam = [...team];
      updatedTeam[index] = {
        name: details.name,
        sprite: details.sprites.front_default,
        id: details.id
      };
      setTeam(updatedTeam);
      setSearch('');
      setResults([]);
    } else {
      alert('Tu equipo ya está completo');
    }
  };

  const removeFromTeam = index => {
    const updatedTeam = [...team];
    updatedTeam[index] = null;
    setTeam(updatedTeam);
  };

  const clearTeam = () => {
    setTeam(Array(6).fill(null));
  };

  return (
    <div className="team-page">
      <h1>¡Crea tu equipo Pokémon!</h1>

      <input
        type="text"
        value={search}
        onChange={handleSearch}
        placeholder="Buscar Pokémon..."
        className="search-bar"
      />

      <ul className="search-results">
        {results.map((p, i) => (
          <li key={i} onClick={() => addToTeam(p)}>
            {p.name.charAt(0).toUpperCase() + p.name.slice(1)}
          </li>
        ))}
      </ul>

      <div className="team-grid">
        {team.map((p, i) => (
          <div key={i} className="team-slot">
            {p ? (
              <>
                <img src={p.sprite} alt={p.name} />
                <span>{p.name.charAt(0).toUpperCase() + p.name.slice(1)}</span>
                <button onClick={() => removeFromTeam(i)}>Eliminar</button>
              </>
            ) : (
              <span className="empty">Vacío</span>
            )}
          </div>
        ))}
      </div>

      <Button className="clear-button" onClick={clearTeam}>Limpiar equipo</Button>
    </div>
  );
};

export default Team;
